13	  return ts ? new Date(ts).toLocaleString('zh-CN') : '—';
14	}
15	function num(v) { return v != null ? v : '—'; }
16	function editLink(productId) { return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId; }
17	function itemsHtml(items, label, color) {
18	  if (!Array.isArray(items) || !items.length) return '';
19	  return `<div class="items">${esc(label)}${items.map((it) =>
20	    `<a href="${esc(editLink(it.productId))}" target="_blank" style="color:${color}" title="SKC ${esc(it.skc || '-')}">• ${esc((it.name || '商品').slice(0, 22))}</a>`
21	  ).join('')}</div>`;
22	}
23	
24	async function refresh() {
25	  const s = await send('getStatus');
26	  const cfg = (s && s.config) || {};
27	  const stores = (s && s.stores) || {};
28	
29	  document.getElementById('cfg').textContent =
30	    '飞书：' + (cfg.webhook ? (cfg.enabled ? '已启用' : '已停用') : '未配置')
31	    + '　后台：' + (s && s.bgVersion ? s.bgVersion : '旧版·需强制刷新');
32	
33	  const lc = s && s.lastCycle;
34	  const ci = document.getElementById('cycleInfo');
35	  if (lc && lc.ts) {
36	    const failed = /失败|没找到|打不开/.test(lc.summary || '');
37	    ci.textContent = '上次轮巡：' + fmtTs(lc.ts) + (failed ? '（有异常，点轮巡重试）' : '');
38	    ci.className = failed ? 'sub err' : 'sub';
39	  } else {
40	    ci.textContent = '';
41	  }
42	
43	  const names = Object.keys(stores).sort();
44	  const box = document.getElementById('stores');
45	  if (names.length === 0) {
46	    box.innerHTML = '<div class="empty">还没有数据。切到某个店的商品列表页（并点“立即检查”）即可开始监测该店。</div>';
47	    return;
48	  }
49	  box.innerHTML = names.map((name) => {
50	    const L = (stores[name] && stores[name].latest) || {};
51	    return `<div class="store">
52	      <div class="name"><span>🏬 ${esc(name)}</span><span class="r"><span class="t">${fmtTs(L.ts)}</span><span class="del" data-name="${esc(name)}" title="删除该店">✕</span></span></div>
53	      <div class="kv">
54	        <span>在售 <b>${num(L.onSale)}</b></span>
55	        <span>流量待关注 <b>${num(L.trafficWatch)}</b></span>
56	        <span>流量下降 <b style="${typeof L.trafficDecline === 'number' && L.trafficDecline > 0 ? 'color:#d92d20' : ''}">${typeof L.trafficDecline === 'number' ? L.trafficDecline : '—'}</b></span>
57	        <span>总数 ${num(L.total)}</span>
58	        <span>未发布/已下架 ${num(L.unpublished)}/${num(L.removed)}</span>
59	      </div>
60	      ${itemsHtml(L.watchItems, '限流商品：', '#d97706')}
61	      ${itemsHtml(L.declineItems, '流量下降：', '#d92d20')}
62	    </div>`;
63	  }).join('');
64	  box.querySelectorAll('.del').forEach((el) => {
65	    el.addEventListener('click', async () => {
66	      const name = el.getAttribute('data-name');
67	      if (!confirm('确定删除「' + name + '」的监测数据？')) return;
68	      const r = await send('deleteStore', { name });
69	      setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
70	      refresh();
71	    });
72	  });
73	}
74	
75	async function addStore() {
76	  const input = document.getElementById('newStore');
77	  const name = input.value.trim();
78	  if (!name) { setMsg('请输入店铺名', 'err'); return; }
79	  const r = await send('addStore', { name });
80	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
81	  if (r && r.ok) { input.value = ''; refresh(); }
82	}
83	
84	document.getElementById('add').addEventListener('click', addStore);
85	document.getElementById('newStore').addEventListener('keydown', (e) => { if (e.key === 'Enter') addStore(); });
86	
87	document.getElementById('cycle').addEventListener('click', async () => {
88	  setMsg('正在轮巡所有店（会切店，约 1-2 分钟，请勿操作页面）…');
89	  const r = await send('cycleNow');
90	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
91	  setTimeout(refresh, 1500);
92	});
93	document.getElementById('check').addEventListener('click', async () => {
94	  setMsg('正在刷新后台页…');
95	  const r = await send('checkNow');
96	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
97	  setTimeout(refresh, 4000);
98	});
99	document.getElementById('test').addEventListener('click', async () => {
100	  setMsg('正在发送测试…');
101	  const r = await send('testFeishu');
102	  setMsg(r && r.msg, r && r.ok ? 'ok' : 'err');
103	});
104	document.getElementById('opt').addEventListener('click', (e) => {
105	  e.preventDefault();
106	  chrome.runtime.openOptionsPage();
107	});
108	
109	refresh();
